// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ProductionOutcomeDeterminer_supervisorProcess_productionOutcomeDeterminer_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_productionOutcomeDeterminer)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_productionOutcomeDeterminer)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_productionOutcomeDeterminer)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_productionOutcomeDeterminer)
  }

  /** helper function to set the values of all input ports.
   * @param outcomeFact payload for data port outcomeFact
   * @param appliedSnapshot payload for data port appliedSnapshot
   */
  def put_concrete_inputs(outcomeFact : Factory_Flow.OutcomeFact,
                          appliedSnapshot : Factory_Flow.FlowSnapshot): Unit = {
    put_outcomeFact(outcomeFact)
    put_appliedSnapshot(appliedSnapshot)
  }


  /** helper function to check ProductionOutcomeDeterminer_supervisorProcess_productionOutcomeDeterminer's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param productionOutcome method that will be called with the value of the outgoing data
   *        port 'productionOutcome'.
   */
  def check_concrete_output(productionOutcome: Factory_Flow.ProductionOutcome => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val productionOutcomeValue: Factory_Flow.ProductionOutcome = get_productionOutcome().get
    if(!productionOutcome(productionOutcomeValue)) {
      testFailures = testFailures :+ st"'productionOutcome' did not match expected: value of the outgoing data port is ${productionOutcomeValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_outcomeFact(value : Factory_Flow.OutcomeFact): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_productionOutcomeDeterminer.operational_api.outcomeFact_Id, Factory_Flow.OutcomeFact_Payload(value))
  }

  // setter for in DataPort
  def put_appliedSnapshot(value : Factory_Flow.FlowSnapshot): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_productionOutcomeDeterminer.operational_api.appliedSnapshot_Id, Factory_Flow.FlowSnapshot_Payload(value))
  }

  // getter for out DataPort
  def get_productionOutcome(): Option[Factory_Flow.ProductionOutcome] = {
    val value: Option[Factory_Flow.ProductionOutcome] = get_productionOutcome_payload() match {
      case Some(Factory_Flow.ProductionOutcome_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port productionOutcome.  Expecting 'Factory_Flow.ProductionOutcome_Payload' but received ${v}")
      case _ => None[Factory_Flow.ProductionOutcome]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_productionOutcome_payload(): Option[Factory_Flow.ProductionOutcome_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_productionOutcomeDeterminer.initialization_api.productionOutcome_Id).asInstanceOf[Option[Factory_Flow.ProductionOutcome_Payload]]
  }

}
